const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15',task:'M9 5h10v16H5V5h4m0-2h6v4H9z M8 12l2 2 5-5 M8 18h8',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chart:'M4 20V10m8 10V4m8 16v-7 M2 22h20',headphones:'M3 14v-3a9 9 0 0 1 18 0v3 M3 13h4v8H3z M17 13h4v8h-4z',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',logout:'M9 3H3v18h6 M9 12h12m-4-4 4 4-4 4',play:'m8 4 12 8-12 8z',flag:'M5 22V3c5-4 9 4 15 0v11c-6 4-10-4-15 0',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6z m-5 10 3 3 7-7',volume:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M8 16a6 6 0 0 1 8 0 M12 20h.01',trophy:'M8 3h8v8a4 4 0 0 1-8 0z M8 5H3v3a5 5 0 0 0 5 5 M16 5h5v3a5 5 0 0 1-5 5 M12 15v6 M7 21h10',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',mail:'M2 4h20v16H2z m0 0 10 9L22 4',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4',menu:'M3 6h18M3 12h18M3 18h18',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 1-2 4 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',refresh:'M20 7V2m0 5h-5 M20 7a9 9 0 1 0 1 9',back:'M19 12H5m6-6-6 6 6 6',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const state={user:null,data:null,page:'dashboard',filter:'all',query:'',attempt:null,index:0,review:false,wrongOnly:false,sync:'saved',saving:Promise.resolve(),pending:false,audioReady:false,audioBusy:false,online:navigator.onLine};
const pageNames={dashboard:'Tổng quan',library:'Thư viện đề thi',assigned:'Bài được giao',history:'Lịch sử làm bài',progress:'Tiến độ học tập'};
let toastTimer,ticker;
function toast(message){$('#toast').innerHTML=esc(message);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(url,method='GET',data){
 const res=await fetch('/api'+url,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});
 const result=await res.json();if(!res.ok){const err=new Error(result.error||'Không thể kết nối máy chủ.');err.status=res.status;throw err;}return result;
}
function modal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Thông tin"><button class="icon-button modal-close" data-action="close-modal" aria-label="Đóng">${icon('close')}</button>${html}</section></div>`;$('#modal-root').querySelector('input,button:not(.modal-close),select')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';}
const dateLabel=ts=>new Date(ts).toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'});
const timeLabel=ts=>new Date(ts).toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'});
const formatTime=seconds=>`${String(Math.floor(Math.max(0,seconds)/60)).padStart(2,'0')}:${String(Math.max(0,seconds)%60).padStart(2,'0')}`;
const completed=()=>state.data.attempts.filter(a=>a.status==='completed');
const initials=()=>esc(state.user.name.split(' ').filter(Boolean).slice(-2).map(s=>s[0]).join('').toUpperCase());
function brand(){return `<div class="brand"><span class="brand-mark">T<span>·</span></span><span>TOEIC<span class="brand-light">studio</span></span></div>`;}
