function renderAuth(register=false){
 clearInterval(ticker);state.page='auth';
 $('#app').innerHTML=`<div class="auth-page"><div class="auth-story">${brand()}<div class="auth-story-content"><span class="eyebrow light">YOUR NEXT CHAPTER STARTS HERE</span><h1>Mục tiêu lớn.<br>Bắt đầu từ những<br><em>bước nhỏ.</em></h1><p>Một không gian yên tĩnh để tập trung luyện thi,<br>hiểu rõ bản thân và tiến bộ mỗi ngày.</p>${illustration()}<div class="auth-features"><span>${icon('check')} Lưu tiến độ tự động</span><span>${icon('check')} Chữa bài chi tiết</span></div></div><span class="auth-foot">Học theo nhịp của bạn. Tiến xa theo cách của bạn.</span></div><main class="auth-form-area"><div class="auth-mobile-brand">${brand()}</div><div class="auth-form-wrap"><span class="pill">${icon('spark')} Không gian học tập của bạn</span><h2>${register?'Bắt đầu hành trình mới':'Chào mừng bạn trở lại'}<span class="dot">.</span></h2><p class="muted">${register?'Tạo tài khoản và cùng chinh phục mục tiêu TOEIC.':'Sẵn sàng cho một bước tiến mới hôm nay?'}</p><div class="auth-tabs"><button class="${!register?'active':''}" data-action="auth-login">Đăng nhập</button><button class="${register?'active':''}" data-action="auth-register">Đăng ký</button></div><form id="auth-form" data-register="${register}">${register?'<label>Họ và tên<input name="name" placeholder="Tên của bạn" required maxlength="60" autocomplete="name"></label>':''}<label>Email<input type="email" name="email" placeholder="ban@example.com" required autocomplete="email"></label><label>Mật khẩu<input type="password" name="password" placeholder="${register?'Ít nhất 8 ký tự':'Nhập mật khẩu của bạn'}" required minlength="${register?8:1}" maxlength="128" autocomplete="${register?'new-password':'current-password'}"></label><div class="form-error" role="alert"></div><button class="button primary full" type="submit">${register?'Tạo tài khoản':'Đăng nhập'} ${icon('arrow')}</button></form><div class="divider-text"><span>hoặc khám phá trước</span></div><button class="button full demo-button" data-action="demo">${icon('play')} Trải nghiệm với tài khoản demo</button><p class="privacy-note">${icon('lock')} Bản chạy localhost · Dữ liệu lưu trên máy của bạn</p></div><span class="auth-copyright">TOEIC Studio © ${new Date().getFullYear()} · Made for your progress</span></main></div>`;
}
async function loadDashboard(page=state.page==='auth'?'dashboard':state.page){state.data=await api('/dashboard');state.user=state.data.user;state.page=page;renderShell();}
function navItem(id,name,symbol,badge=''){return `<button class="nav-item ${state.page===id?'active':''}" data-nav="${id}">${icon(symbol)}<span>${name}</span>${badge?`<span class="nav-count">${badge}</span>`:''}</button>`;}
function renderShell(){
 clearInterval(ticker);window.speechSynthesis?.cancel();state.attempt=null;state.review=false;
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<div class="workspace-label">KHÔNG GIAN HỌC TẬP</div><nav>${navItem('dashboard','Tổng quan','grid')}${navItem('library','Thư viện đề thi','book')}${navItem('assigned','Bài được giao','task','1')}${navItem('history','Lịch sử làm bài','clock')}${navItem('progress','Tiến độ học tập','chart')}</nav><div class="sidebar-bottom"><div class="sidebar-tip"><div class="tip-icon">${icon('spark')}</div><strong>Mỗi nỗ lực đều đáng giá.</strong><p>15 phút hôm nay, thêm tự tin cho ngày mai.</p><button data-action="study-guide">Một chút cảm hứng ${icon('arrow')}</button></div><button class="nav-item" data-action="guide">${icon('help')}<span>Hướng dẫn sử dụng</span></button><button class="nav-item" data-action="profile">${icon('settings')}<span>Cài đặt tài khoản</span></button><div class="sidebar-user"><span class="avatar">${initials()}</span><div><strong>${esc(state.user.name)}</strong><small>Thành viên học tập</small></div><button class="icon-button" data-action="logout" aria-label="Đăng xuất">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><span>Không gian học tập</span>${icon('chevron')}<strong>${pageNames[state.page]}</strong></div><div class="topbar-actions"><span class="local-status"><i></i> Local workspace</span><button class="icon-button" data-action="notifications" aria-label="Thông báo">${icon('bell')}<span class="notification-dot"></span></button><button class="avatar small" data-action="profile" aria-label="Tài khoản">${initials()}</button></div></header><main class="page-content">${renderPage()}</main><footer class="page-footer"><span>TOEIC Studio <span class="footer-dot">·</span> Từng bước nhỏ, chạm mục tiêu lớn.</span><span>Đề minh họa · Không phải đề thi chính thức ETS</span></footer></div></div>`;
}
function heading(kicker,title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function renderPage(){
 if(state.page==='dashboard')return dashboard();
 if(state.page==='library'||state.page==='assigned')return library();
 if(state.page==='history')return historyPage();
 return progressPage();
}
function dashboard(){
 const done=completed(),last=done[0],active=state.data.attempts.find(a=>a.status==='active');
 const minutes=done.reduce((sum,a)=>sum+Math.max(1,Math.round((a.completedAt-a.startedAt)/60000)),0);
 const days=new Set(done.map(a=>new Date(a.completedAt).toDateString())).size;
 return `${heading('LET’S MAKE PROGRESS',`Chào ${esc(state.user.email.endsWith('@local.demo')?'bạn':state.user.name)}, hôm nay học gì? <span class="greeting-sun">${icon('sun')}</span>`,'Một chút tập trung hôm nay, thêm một bước gần đến mục tiêu.',`<span class="date-chip">${icon('clock')} ${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'2-digit',month:'long'})}</span>`)}<div class="hero-grid"><section class="hero"><div class="hero-copy"><span class="hero-tag"><span></span> HÀNH TRÌNH CHINH PHỤC TOEIC</span><h2>Mỗi ngày một chút.<br>Tiến gần hơn <em>mục tiêu.</em></h2><p>Luyện tập đúng nhịp, theo dõi từng bước tiến.<br>Phiên bản tốt hơn của bạn bắt đầu từ đây.</p><button class="button primary" data-nav="library">Khám phá đề thi ${icon('arrow')}</button><div class="hero-note">${icon('shield')} Học chủ động · Tiến bộ bền vững</div></div>${illustration()}</section><section class="target-card"><div class="card-label">${icon('target')} MỤC TIÊU CỦA BẠN<button class="text-button" data-action="profile">Sửa</button></div><div class="target-gauge"><svg viewBox="0 0 200 110" aria-hidden="true"><path d="M20 95a80 80 0 0 1 160 0" fill="none" stroke="#eef0e9" stroke-width="13" stroke-linecap="round"/><path d="M20 95a80 80 0 0 1 160 0" fill="none" stroke="#567859" stroke-width="13" stroke-linecap="round" pathLength="100" stroke-dasharray="${last?.stats.accuracy||0} 100"/></svg><div><strong>${state.user.target}</strong><span>điểm TOEIC mục tiêu</span></div></div><div class="target-caption"><span>Độ chính xác gần nhất</span><strong>${last?last.stats.accuracy+'%':'Chưa có'}</strong></div><p>${last?'Mỗi lần luyện tập là một cơ hội tiến bộ.':'Bắt đầu bài đầu tiên để hiểu rõ khả năng của bạn.'}</p><span class="tiny muted">Tiến độ dựa trên độ chính xác, không quy đổi điểm TOEIC.</span></section></div><div class="stats-grid">${statCard('book',done.length,'Bài đã hoàn thành','Cùng tích lũy trải nghiệm','sage')}${statCard('target',last?last.stats.accuracy+'%':'—','Độ chính xác gần nhất',last?'Tiếp tục giữ nhịp học nhé':'Sẵn sàng cho bài đầu tiên','peach')}${statCard('clock',minutes+' <small>phút</small>','Thời gian làm bài','Từng phút đều có ý nghĩa','blue')}${statCard('spark',days+' <small>ngày</small>','Ngày đã luyện tập','Xây thói quen, tạo bứt phá','lavender')}</div>${active?`<section class="resume-banner"><span class="resume-icon">${icon('play')}</span><div><strong>Tiếp tục điều bạn đang bắt đầu</strong><p>${esc(active.title)} · Đã trả lời ${Object.keys(active.answers).length}/${active.questionCount} câu</p></div><button class="button primary" data-resume="${active.id}">Tiếp tục làm bài ${icon('arrow')}</button></section>`:''}<div class="dashboard-bottom"><section><div class="section-heading"><div><h2>Đề thi dành cho bạn <span class="count-chip">03</span></h2><p>Chọn một đề phù hợp và bắt đầu hành trình.</p></div><button class="text-button" data-nav="library">Xem tất cả ${icon('arrow')}</button></div><div class="exam-grid dashboard-exams">${state.data.exams.filter(e=>['journey-01','reading-01','listening-01'].includes(e.id)).map(examCard).join('')}</div><div class="recent-block"><div class="section-heading"><h2>Hoạt động gần đây</h2><button class="text-button" data-nav="history">Lịch sử làm bài ${icon('arrow')}</button></div>${done.length?historyTable(done.slice(0,3)):emptyState('clock','Một trang mới đang chờ bạn','Bài thi đầu tiên sẽ là cột mốc đầu tiên trong hành trình của bạn.','Chọn đề thi','library')}</div></section><aside class="right-column">${weeklyCard()}<div class="small-tip"><span class="eyebrow">MỘT CHÚT MẸO NHỎ</span><div class="tip-quote">“</div><h3>Đừng chỉ đếm câu đúng.<br>Hãy hiểu cả câu sai.</h3><p>Dành vài phút xem lại lời giải sau mỗi bài thi. Đó là lúc bạn học được nhiều nhất.</p><span>${icon('book')} Học sâu hơn, nhớ lâu hơn</span></div></aside></div>`;
}
function statCard(symbol,value,label,note,color){return `<section class="stat-card"><span class="stat-icon ${color}">${icon(symbol)}</span><div><strong>${value}</strong><span>${label}</span></div><small>${note}</small></section>`;}
function weeklyCard(){
 const today=new Date();const monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));monday.setHours(0,0,0,0);
 const dates=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return d;});
 const practiced=new Set(completed().map(a=>new Date(a.completedAt).toDateString()));
 return `<section class="week-card"><div class="section-heading"><h3>Nhịp học tuần này</h3>${icon('spark')}</div><p>Duy trì thói quen nhỏ mỗi ngày.</p><div class="week-days">${dates.map((d,i)=>`<div><span>${['T2','T3','T4','T5','T6','T7','CN'][i]}</span><b class="${d.toDateString()===today.toDateString()?'today':''} ${practiced.has(d.toDateString())?'practiced':''}">${practiced.has(d.toDateString())?icon('check'):d.getDate()}</b></div>`).join('')}</div><div class="week-note"><span class="legend-dot"></span> ${dates.filter(d=>practiced.has(d.toDateString())).length}/7 ngày đã hoàn thành bài</div></section>`;
}
function examCard(e){
 const symbol=e.category==='listening'?'headphones':e.category==='reading'?'book':e.category==='assigned'?'task':'book';
 const parts=e.parts.length===7?'Part 1–7':e.parts.map(p=>'P'+p).join(' · ');
 return `<article class="exam-card"><div class="exam-cover ${e.color}"><span class="cover-label">${e.category==='reading'?'READ & DISCOVER':e.category==='listening'?'LISTEN & CONNECT':e.category==='assigned'?'YOUR NEXT MILESTONE':'A LITTLE PRACTICE, A BIG DIFFERENCE'}</span><div class="cover-art">${icon(symbol)}<span class="cover-orbit one"></span><span class="cover-orbit two"></span><span class="cover-star">✦</span><span class="cover-line"></span></div><span class="cover-type">${e.category==='reading'?'READING':e.category==='listening'?'LISTENING':'TOEIC'}<b>${e.id.endsWith('02')?'02':'01'}</b></span></div><div class="exam-details"><div class="exam-badges"><span class="pill small-pill ${e.category==='assigned'?'purple-pill':''}">${esc(e.tag)}</span><span class="exam-level"><i></i>${e.level}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.subtitle)}</p><div class="exam-meta"><span>${icon('task')} ${e.questionCount||'—'} câu</span><span>${icon('clock')} ${e.minutes} phút</span><span>${parts||'Sắp mở'}</span></div><div class="exam-card-bottom"><span class="demo-tag">ĐỀ MINH HỌA</span><button class="text-button" data-exam="${e.id}" ${!e.access?'disabled':''}>${e.access?'Làm bài':'Chưa mở'} ${icon(e.access?'arrow':'lock')}</button></div></div></article>`;
}
function library(){
 const assigned=state.page==='assigned';
 let exams=state.data.exams.filter(e=>assigned?e.category==='assigned':e.category!=='assigned');
 if(!assigned&&state.filter!=='all')exams=exams.filter(e=>e.category===state.filter);
 if(state.query)exams=exams.filter(e=>(e.title+' '+e.subtitle).toLowerCase().includes(state.query.toLowerCase()));
 return `${heading(assigned?'YOUR NEXT MILESTONE':'FIND YOUR NEXT CHALLENGE',assigned?'Bài được giao':'Một đề thi. Một bước tiến.',assigned?'Hoàn thành bài được giao theo nhịp học của bạn.':'Thi thử để kiểm tra năng lực, luyện tập để xây nền vững chắc.')}<div class="info-banner">${icon('info')}<p>Đây là bộ đề minh họa rút gọn để trải nghiệm hệ thống. Bài TOEIC Listening & Reading đầy đủ có 200 câu, thời gian làm bài khoảng 120 phút.</p></div>${assigned?'':`<div class="library-toolbar"><div class="filter-tabs">${[['all','Tất cả đề'],['full','Tổng hợp'],['listening','Listening'],['reading','Reading']].map(([id,label])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="exam-search" placeholder="Tìm một đề thi…" value="${esc(state.query)}" aria-label="Tìm đề thi"></label></div>`}<div id="exam-results"><div class="results-count">${exams.length} đề thi ${assigned?'được giao':'dành cho bạn'}</div><div class="exam-grid library-exams">${exams.map(examCard).join('')}</div>${!exams.length?emptyState('search','Chưa tìm thấy đề phù hợp','Thử một từ khóa khác nhé.'):''}</div>`;
}
function emptyState(symbol,title,text,action,nav){return `<div class="empty-state"><span>${icon(symbol)}</span><h3>${title}</h3><p>${text}</p>${action?`<button class="button secondary" data-nav="${nav}">${action} ${icon('arrow')}</button>`:''}</div>`;}
function historyTable(attempts){return `<div class="table-wrap"><table><thead><tr><th>ĐỀ THI</th><th>THỜI GIAN</th><th>KẾT QUẢ</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${attempts.map(a=>`<tr><td><strong>${esc(a.title)}</strong><small>${a.mode==='exam'?'Thi thử':'Luyện tập'}</small></td><td>${timeLabel(a.completedAt||a.startedAt)}</td><td>${a.stats?`<strong>${a.stats.correct}/${a.stats.total}</strong> <span class="muted">· ${a.stats.accuracy}%</span>`:`${Object.keys(a.answers).length}/${a.questionCount} câu`}</td><td><span class="status-pill ${a.status==='active'?'in-progress':''}">${a.status==='active'?'Đang làm':'Đã hoàn thành'}</span></td><td><button class="text-button" data-${a.status==='active'?'resume':'result'}="${a.id}">${a.status==='active'?'Tiếp tục':'Kết quả'} ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function historyPage(){return `${heading('EVERY ATTEMPT COUNTS','Nhìn lại để tiến xa hơn.','Mỗi bài làm lưu lại một bước tiến của bạn.')}<section class="panel">${state.data.attempts.length?historyTable(state.data.attempts):emptyState('clock','Hành trình của bạn bắt đầu từ đây','Hoàn thành một bài thi để xem kết quả và lịch sử làm bài.','Khám phá đề thi','library')}</section>`;}
function progressPage(){
 const done=completed();const totals=Array.from({length:7},(_,i)=>{const values=done.flatMap(a=>a.stats.parts).filter(p=>p.part===i+1);return {part:i+1,total:values.reduce((n,p)=>n+p.total,0),correct:values.reduce((n,p)=>n+p.correct,0)};});
 return `${heading('SMALL STEPS, REAL GROWTH','Tiến bộ theo cách của bạn.','Theo dõi độ chính xác và khám phá kỹ năng cần luyện thêm.')}<div class="progress-layout"><section class="panel padded"><h2>Độ chính xác theo từng Part</h2><p class="muted">Tổng hợp từ ${done.length} bài đã hoàn thành.</p>${totals.map(p=>`<div class="part-progress"><div><strong>Part ${p.part}</strong><span>${p.total?p.correct+'/'+p.total+' câu đúng':'Chưa có dữ liệu'}</span></div><div class="progress-track"><span style="width:${p.total?p.correct/p.total*100:0}%"></span></div></div>`).join('')}</section><section class="panel padded"><h2>Những bước tiến gần đây</h2><div class="accuracy-chart">${done.length?done.slice(0,8).reverse().map((a,i)=>`<div class="chart-column"><strong>${a.stats.accuracy}%</strong><div style="height:${Math.max(4,a.stats.accuracy*1.6)}px" title="${esc(a.title)}"></div><span>Bài ${i+1}</span></div>`).join(''):emptyState('chart','Chưa có dữ liệu','Làm bài đầu tiên để bắt đầu theo dõi.')}</div><p class="tiny muted">Biểu đồ thể hiện tỷ lệ trả lời đúng trên các bộ đề minh họa, không phải điểm TOEIC quy đổi.</p><button class="button primary" data-nav="library">Luyện tập tiếp ${icon('arrow')}</button></section></div>`;
}
function openSetup(id){
 const e=state.data.exams.find(e=>e.id===id);if(!e?.access)return;state.audioReady=false;
 modal(`<span class="modal-symbol sage">${icon('headphones')}</span><span class="eyebrow">CHUẨN BỊ MỘT CHÚT, TỰ TIN HƠN</span><h2>${esc(e.title)}</h2><p class="muted">${e.questionCount} câu hỏi · ${e.minutes} phút · ${e.parts.map(p=>'Part '+p).join(', ')}</p><form id="setup-form" data-exam-id="${e.id}"><div class="mode-options"><label class="mode-option"><input type="radio" name="mode" value="exam" checked><span><strong>${icon('clock')} Thi thử</strong><small>Đếm ngược, khóa Listening khi hết thời gian phần nghe.</small></span></label><label class="mode-option"><input type="radio" name="mode" value="practice"><span><strong>${icon('book')} Luyện tập</strong><small>Không giới hạn thời gian, tự do chuyển câu và nghe lại.</small></span></label></div><div class="rules-box"><strong>Trước khi bắt đầu</strong><ul><li>Đáp án tự động lưu trên máy chủ localhost; khi mất kết nối, bản nháp giữ trong trình duyệt.</li><li>Thi thử: ${e.listeningMinutes?`Listening ${e.listeningMinutes} phút${e.category==='full'||e.category==='assigned'?`, sau đó Reading ${e.minutes-e.listeningMinutes} phút`:''}.`:`Reading ${e.minutes} phút.`} Hết giờ sẽ tự nộp bài.</li><li>${e.releaseDelay?'Bài được giao mở đáp án và transcript 5 phút sau khi nộp ở chế độ thi thử.':'Kết quả, lời giải và transcript mở sau khi nộp bài.'}</li><li>Audio mẫu dùng giọng đọc tiếng Anh của trình duyệt, không phải audio ETS. Có thể thử lại nếu âm thanh lỗi.</li></ul></div>${e.listeningMinutes?`<div class="audio-check"><div>${icon('volume')}<span><strong>Kiểm tra tai nghe</strong><small id="audio-check-status">Bấm nghe thử và xác nhận bạn nghe rõ.</small></span></div><button class="button secondary compact" type="button" data-action="test-audio">${icon('play')} Nghe thử</button></div><label class="checkbox-label"><input type="checkbox" id="heard-audio" required> Tôi đã nghe rõ âm thanh mẫu.</label>`:''}<label class="checkbox-label"><input type="checkbox" name="rules" required> Tôi đã hiểu quy tắc và sẵn sàng làm bài.</label><div class="form-error" role="alert"></div><button type="submit" class="button primary full">Bắt đầu làm bài ${icon('arrow')}</button></form>`);
}
function speak(text,onEnd){
 if(!('speechSynthesis'in window)){toast('Trình duyệt chưa hỗ trợ đọc tiếng Anh. Hãy dùng Chrome hoặc Edge.');return false;}
 window.speechSynthesis?.cancel();const utter=new SpeechSynthesisUtterance(text);utter.lang='en-US';utter.rate=.85;
 const voices=speechSynthesis.getVoices();utter.voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'))||null;
 utter.onend=()=>{state.audioBusy=false;onEnd?.();};utter.onerror=e=>{state.audioBusy=false;if(e.error!=='interrupted'&&e.error!=='canceled')toast('Âm thanh chưa phát được. Kiểm tra thiết bị và bấm nghe lại.');};
 state.audioBusy=true;speechSynthesis.speak(utter);return true;
}
function draftKey(){return 'toeic-draft-'+state.attempt.id;}
function keepDraft(){try{localStorage.setItem(draftKey(),JSON.stringify({answers:state.attempt.answers,flags:state.attempt.flags}));}catch{toast('Trình duyệt không lưu được bản nháp. Giữ kết nối với máy chủ.');}}
function saveBadge(){const el=$('#save-state');if(el){el.className='save-state '+state.sync;el.innerHTML=icon(state.sync==='saved'?'check':state.sync==='saving'?'refresh':'wifi')+({saved:'Đã lưu trên máy chủ',saving:'Đang lưu…',offline:'Chưa đồng bộ · đã lưu bản nháp',error:'Chưa đồng bộ · cần thử lại'}[state.sync]);}}
function syncAnswers(){
 state.pending=true;
 state.saving=state.saving.catch(()=>{}).then(async()=>{
  if(!state.pending||!state.attempt||state.attempt.status!=='active')return;
  state.pending=false;const id=state.attempt.id;const answers={...state.attempt.answers},flags=[...state.attempt.flags];
  state.sync='saving';saveBadge();
  try{const saved=await api(`/attempts/${id}/answers`,'PATCH',{answers,flags});if(state.attempt?.id===id){state.attempt.savedAt=saved.savedAt;state.sync=state.pending?'saving':'saved';if(!state.pending)localStorage.removeItem(draftKey());saveBadge();}}
  catch(err){state.sync=navigator.onLine?'error':'offline';saveBadge();if(err.status===409){
   toast(err.message);
   if(state.attempt?.deadline&&Date.now()>=state.attempt.deadline)await finishAttempt(true);
   else if(state.attempt?.id===id&&listeningLocked()){
    try{const canonical=await api('/attempts/'+id);if(canonical.status==='completed'){showResult(canonical);return;}
     const current=state.attempt;canonical.questions.filter(q=>q.section==='reading').forEach(q=>{if(current.answers[q.id]!==undefined)canonical.answers[q.id]=current.answers[q.id];});canonical.flags=current.flags;state.attempt=canonical;keepDraft();renderExam();syncAnswers();
    }catch{}
   }
  }}
 });return state.saving;
}
async function openAttempt(id){
 const a=await api('/attempts/'+id);if(a.status==='completed'){showResult(a);return;}
 state.attempt=a;state.index=0;state.review=false;state.sync='saved';
 try{const draft=JSON.parse(localStorage.getItem(draftKey())||'null');if(draft){
  const allowed=a.questions.filter(q=>!(a.mode==='exam'&&a.listeningDeadline&&Date.now()>=a.listeningDeadline&&q.section==='listening')).map(q=>String(q.id));
  Object.entries(draft.answers||{}).forEach(([id,value])=>{if(allowed.includes(id))a.answers[id]=value;});a.flags=draft.flags||[];state.sync='offline';syncAnswers();toast('Đã khôi phục bản nháp trên trình duyệt.');
 }}catch{}
 if(listeningLocked())state.index=Math.max(0,a.questions.findIndex(q=>q.section==='reading'));
 renderExam();
}
function listeningLocked(){return state.attempt?.mode==='exam'&&state.attempt.listeningDeadline&&Date.now()>=state.attempt.listeningDeadline;}
function questionLocked(q){return !state.review&&state.attempt.mode==='exam'&&(q.section==='reading'&&state.attempt.listeningDeadline&&Date.now()<state.attempt.listeningDeadline||q.section==='listening'&&listeningLocked());}
function visibleQuestions(){return state.wrongOnly&&state.review?state.attempt.questions.filter(q=>state.attempt.answers[q.id]!==q.correct):state.attempt.questions;}
function scene(kind){return kind==='library'?`<svg class="scene" viewBox="0 0 560 300" role="img" aria-label="Một người phụ nữ đang đặt sách lên kệ thư viện"><rect width="560" height="300" fill="#e9eae5"/><path d="M40 30h215v245H40zM338 30h180v245H338z" fill="#c5c8bf"/><path d="M40 105h215M40 185h215M338 105h180M338 185h180" stroke="#7b8379" stroke-width="9"/>${Array.from({length:15},(_,i)=>`<rect x="${52+(i%5)*39}" y="${46+Math.floor(i/5)*80}" width="26" height="55" rx="2" fill="${['#7c8a80','#a4a99e','#59685e'][i%3]}"/>`).join('')}${Array.from({length:12},(_,i)=>`<rect x="${350+(i%4)*39}" y="${46+Math.floor(i/4)*80}" width="25" height="55" fill="#8c9589"/>`).join('')}<circle cx="289" cy="92" r="24" fill="#b9a18c"/><path d="M266 87c-1-41 52-37 49 4l-10-12-31-3z" fill="#4c554f"/><path d="m272 120-15 95h67l-19-95" fill="#778a80"/><path d="m279 209-5 76m30-76 9 76" stroke="#49584f" stroke-width="18"/><path d="m276 136-34 16-15-54m76 38 26 18" stroke="#b9a18c" stroke-width="13" stroke-linecap="round"/><rect x="212" y="55" width="22" height="45" fill="#4e6453"/></svg>`:`<svg class="scene" viewBox="0 0 560 300" role="img" aria-label="Phòng họp trống với ghế đặt quanh một chiếc bàn"><rect width="560" height="300" fill="#e5e8e3"/><path d="M0 220h560v80H0z" fill="#cbd0c6"/><path d="M45 25h180v130H45zM335 25h180v130H335z" fill="#f9fcf3"/><path d="M135 25v130m290-130v130" stroke="#b0baae" stroke-width="5"/><path d="m130 162-55 60h410l-55-60z" fill="#a0ac98"/><path d="M100 223v60m360-60v60" stroke="#606d5c" stroke-width="10"/>${[140,245,350].map(x=>`<rect x="${x}" y="131" width="58" height="52" rx="8" fill="#657461"/><path d="M${x+8} 183v55m42-55v55" stroke="#657461" stroke-width="8"/><rect x="${x}" y="229" width="58" height="42" rx="8" fill="#798774"/><path d="M${x+8} 271v29m42-29v29" stroke="#596954" stroke-width="7"/>`).join('')}</svg>`;}
function renderExam(){
 const a=state.attempt;const items=visibleQuestions();state.index=Math.max(0,Math.min(state.index,items.length-1));const q=items[state.index];
 if(!q){toast('Không có câu hỏi phù hợp.');return;}
 const reviewing=state.review;
 $('#app').innerHTML=`<div class="exam-layout"><header class="exam-header"><button class="exam-brand-button" data-action="${reviewing?'back-result':'leave-exam'}">${brand()}</button><div class="exam-header-title"><strong>${esc(a.title)}</strong><span>${reviewing?'CHỮA BÀI':a.mode==='exam'?'CHẾ ĐỘ THI THỬ':'CHẾ ĐỘ LUYỆN TẬP'} · ĐỀ MINH HỌA</span></div><div class="exam-header-right">${reviewing?`<button class="button secondary compact" data-action="back-result">${icon('back')} Kết quả</button>`:`<div id="save-state" class="save-state"></div><button class="button primary compact" data-action="submit">Nộp bài ${icon('arrow')}</button>`}</div></header><div class="exam-body"><main class="question-area"><div class="question-topline"><span class="pill">${q.section==='listening'?icon('headphones'):icon('book')} ${q.section==='listening'?'Listening':'Reading'} <span class="middle-dot">·</span> Part ${q.part}</span><span>Câu ${state.index+1} / ${items.length}</span></div>${!reviewing?`<div class="section-instruction">${icon('info')} ${a.mode==='practice'?'Luyện tập theo nhịp của bạn. Có thể nghe lại và chuyển câu tự do.':q.section==='listening'?'Phần Listening đang diễn ra. Có thể chuyển giữa các câu nghe trước khi hết thời gian phần này.':'Phần Reading đang diễn ra. Đáp án Listening đã được khóa.'}</div>`:''}<section class="question-card"><div class="question-heading"><h2>Câu ${q.id.toString().padStart(2,'0')}</h2><button class="flag-button ${a.flags.includes(q.id)?'flagged':''}" data-action="flag" ${reviewing?'disabled':''}>${icon('flag')} ${a.flags.includes(q.id)?'Đã đánh dấu':'Đánh dấu xem lại'}</button></div>${q.scene?scene(q.scene):''}${q.audio?`<div class="audio-player"><button class="audio-play" data-action="play-question" aria-label="Nghe câu hỏi">${icon('play')}</button><div><strong>Audio · Part ${q.part}</strong><span>Giọng đọc mẫu tiếng Anh · Có thể nghe lại</span></div><span class="audio-wave">▂ ▄ ▆ ▃ █ ▅ ▂ ▄ ▆ ▃ ▅ ▂</span></div>`:''}${q.passage?`<div class="reading-passage">${esc(q.passage).replace(/\n/g,'<br>')}</div>`:''}<h3 class="question-prompt">${esc(q.prompt)}</h3><div class="answer-options">${q.options.map((option,i)=>`<button class="answer-option ${a.answers[q.id]===i?'selected':''} ${reviewing&&q.correct===i?'correct':''} ${reviewing&&a.answers[q.id]===i&&i!==q.correct?'incorrect':''}" data-answer="${i}" ${reviewing||questionLocked(q)?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(option)}</span>${reviewing&&q.correct===i?icon('check'):reviewing&&a.answers[q.id]===i&&i!==q.correct?icon('close'):a.answers[q.id]===i?'<span class="selected-dot"></span>':''}</button>`).join('')}</div>${reviewing?`<div class="explanation-box"><strong>${icon('spark')} Giải thích đáp án ${String.fromCharCode(65+q.correct)}</strong><p>${esc(q.explanation)}</p></div>${q.transcript?`<details class="transcript"><summary>${icon('headphones')} Đọc transcript</summary><p>${esc(q.transcript).replace(/\n/g,'<br>')}</p></details>`:''}`:''}</section><div class="question-navigation"><button class="button secondary" data-step="-1" ${state.index===0?'disabled':''}>${icon('back')} Câu trước</button><span>${reviewing?'Hiểu một câu sai, tiến thêm một bước.':'Bình tĩnh, tập trung và tin vào bản thân.'}</span><button class="button primary" data-step="1" ${state.index>=items.length-1?'disabled':''}>Câu tiếp ${icon('arrow')}</button></div></main><aside class="exam-sidebar">${reviewing?`<div class="review-summary"><span class="eyebrow">NHÌN LẠI & TIẾN BỘ</span><h3>${a.stats.correct}/${a.stats.total} câu đúng</h3><label class="checkbox-label"><input id="wrong-filter" type="checkbox" ${state.wrongOnly?'checked':''}> Chỉ xem câu sai / bỏ trống</label></div>`:`<section class="timer-card"><span>${icon('clock')} ${a.mode==='exam'?'THỜI GIAN CÒN LẠI':'LUYỆN TẬP TỰ DO'}</span><strong id="exam-timer">${a.mode==='exam'?'--:--':'∞'}</strong><small id="section-timer">Không giới hạn thời gian</small></section>`}<section class="question-map"><h3>Bảng câu hỏi <span>${Object.keys(a.answers).length}/${a.questions.length}</span></h3>${['listening','reading'].map(section=>{const qs=items.filter(q=>q.section===section);return qs.length?`<div class="map-section"><span>${icon(section==='listening'?'headphones':'book')} ${section==='listening'?'Listening':'Reading'}${!reviewing&&a.mode==='exam'&&(section==='listening'&&listeningLocked()||section==='reading'&&a.listeningDeadline&&Date.now()<a.listeningDeadline)?icon('lock'):''}</span><div class="question-number-grid">${qs.map(q=>`<button class="question-number ${a.answers[q.id]!==undefined?'answered':''} ${q.id===items[state.index].id?'current':''} ${a.flags.includes(q.id)?'marked':''} ${reviewing?(q.correct===a.answers[q.id]?'right':'wrong'):''}" data-question="${q.id}" ${questionLocked(q)?'disabled':''} aria-label="Câu ${q.id}${a.answers[q.id]!==undefined?', đã trả lời':''}${a.flags.includes(q.id)?', đã đánh dấu':''}">${q.id}</button>`).join('')}</div></div>`:'';}).join('')}<div class="map-legend"><span><i class="answered"></i> Đã trả lời</span><span><i></i> Chưa trả lời</span><span><i class="marked"></i> Đánh dấu</span></div></section>${!reviewing?`<div class="connection-note">${icon(state.online?'shield':'wifi')}<span>${state.online?'Tiến độ được tự động lưu sau mỗi lựa chọn.':'Mất kết nối. Bản nháp được giữ trong trình duyệt.'}</span></div><button class="text-button" data-action="retry-sync">${icon('refresh')} Đồng bộ lại</button><button class="text-button exit-exam" data-action="leave-exam">${icon('logout')} Lưu & về tổng quan</button>`:''}</aside></div></div>`;
 if(!reviewing){saveBadge();updateTimer();clearInterval(ticker);ticker=setInterval(updateTimer,1000);}
}
function updateTimer(){
 const a=state.attempt;if(!a||state.review||a.status!=='active')return;
 if(a.deadline){const remaining=Math.ceil((a.deadline-Date.now())/1000);const el=$('#exam-timer');if(el){el.textContent=formatTime(remaining);el.classList.toggle('urgent',remaining<=60);}
  const info=$('#section-timer');if(info)info.textContent=a.listeningDeadline&&Date.now()<a.listeningDeadline?'Listening · '+formatTime(Math.ceil((a.listeningDeadline-Date.now())/1000))+' còn lại':a.questions.some(q=>q.section==='reading')?'Đang làm phần Reading':'Đang hoàn tất lượt thi';
  if(remaining<=0){clearInterval(ticker);finishAttempt(true);return;}
  const q=visibleQuestions()[state.index];if(q?.section==='listening'&&listeningLocked()&&a.questions.some(q=>q.section==='reading')){window.speechSynthesis?.cancel();state.index=a.questions.findIndex(q=>q.section==='reading');renderExam();toast('Đã hết thời gian Listening. Bắt đầu phần Reading.');}
 }
}
async function requestSubmit(){
 const a=state.attempt;const unanswered=a.questions.filter(q=>a.answers[q.id]===undefined).length;
 modal(`<span class="modal-symbol peach">${icon('task')}</span><h2>Bạn sẵn sàng nộp bài?</h2><p class="muted">Hít thở một chút và kiểm tra lại bài làm của bạn.</p><div class="submit-summary"><div><strong>${Object.keys(a.answers).length}</strong><span>Đã trả lời</span></div><div><strong>${unanswered}</strong><span>Chưa trả lời</span></div><div><strong>${a.flags.length}</strong><span>Đã đánh dấu</span></div></div>${unanswered?`<p class="warning-text">Còn ${unanswered} câu chưa trả lời. Các câu này sẽ được tính là bỏ trống.</p>`:''}<p class="tiny muted">Sau khi nộp bài, đáp án được khóa và không thể thay đổi.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Tiếp tục làm bài</button><button class="button primary" data-action="confirm-submit">Xác nhận nộp bài ${icon('check')}</button></div><div class="form-error" role="alert"></div>`);
}
let finishing=false;
async function finishAttempt(automatic=false){
 if(finishing||!state.attempt||state.attempt.status!=='active')return;finishing=true;
 try{
  if(!automatic){await syncAnswers();if(state.sync!=='saved')throw new Error('Đáp án chưa đồng bộ. Kiểm tra kết nối rồi thử nộp lại.');}
  const a=await api(`/attempts/${state.attempt.id}/submit`,'POST');localStorage.removeItem(draftKey());clearInterval(ticker);window.speechSynthesis?.cancel();closeModal();showResult(a);if(automatic)toast('Đã hết giờ. Hệ thống đã khóa và chấm các đáp án được máy chủ chấp nhận.');
 }catch(err){if(automatic){state.sync='error';saveBadge();toast('Hết giờ. Đáp án đã khóa theo thời gian máy chủ. Kết nối lại để nhận kết quả.');}else{const error=$('#modal-root .form-error');if(error)error.textContent=err.message;else toast(err.message);}}
 finally{finishing=false;}
}
function showResult(a){
 clearInterval(ticker);state.attempt=a;state.page='result';state.review=false;const s=a.stats;
 const weakest=[...s.parts].sort((a,b)=>a.correct/a.total-b.correct/b.total).filter(p=>p.correct<p.total).slice(0,2);
 $('#app').innerHTML=`<div class="result-page"><header class="result-header">${brand()}<button class="button secondary compact" data-nav="dashboard">${icon('back')} Về tổng quan</button></header><main class="result-content"><div class="result-intro"><span class="result-trophy">${icon('trophy')}</span><div class="eyebrow">ANOTHER STEP FORWARD</div><h1>Bạn đã hoàn thành. Thật đáng tự hào!</h1><p>Mỗi lần thử sức là một lần hiểu rõ bản thân hơn.</p><span class="result-exam-name">${esc(a.title)} <span>·</span> ${a.mode==='exam'?'Thi thử':'Luyện tập'} <span>·</span> ${timeLabel(a.completedAt)}</span></div><section class="result-score-card"><div class="result-score"><div class="score-circle" style="--accuracy:${s.accuracy}%"><div><strong>${s.accuracy}<small>%</small></strong><span>Độ chính xác</span></div></div><p>Đúng <strong>${s.correct}/${s.total}</strong> câu</p><small>Kết quả trên đề minh họa, không quy đổi điểm TOEIC.</small></div><div class="result-breakdown"><div class="result-counts"><div class="correct-count"><strong>${s.correct}</strong><span>${icon('check')} Câu đúng</span></div><div class="wrong-count"><strong>${s.wrong}</strong><span>${icon('close')} Câu sai</span></div><div><strong>${s.unanswered}</strong><span>Câu bỏ trống</span></div></div>${['listening','reading'].filter(k=>s[k].total).map(k=>`<div class="result-section"><div><strong>${icon(k==='listening'?'headphones':'book')} ${k==='listening'?'Listening':'Reading'}</strong><span>${s[k].correct}/${s[k].total} câu đúng</span></div><div class="progress-track"><span style="width:${s[k].correct/s[k].total*100}%"></span></div></div>`).join('')}<span class="tiny muted">${a.reason==='timeout'?'Hệ thống tự nộp khi hết giờ.':'Bạn đã chủ động nộp bài.'} Đáp án đã được khóa.</span></div></section><div class="result-details"><section class="panel padded"><h2>Nhìn rõ từng kỹ năng</h2><div class="part-results">${s.parts.map(p=>`<div><span>Part ${p.part}</span><strong>${p.correct}/${p.total}</strong><small>${Math.round(p.correct/p.total*100)}% chính xác</small></div>`).join('')}</div></section><section class="next-step-card"><span class="eyebrow">BƯỚC TIẾP THEO</span><h2>${weakest.length?'Biến câu sai thành bài học.':'Giữ vững phong độ của bạn.'}</h2><p>${weakest.length?`Bạn có thể dành thêm thời gian cho ${weakest.map(p=>'Part '+p.part).join(' và ')}. Đọc lời giải và nghe lại để hiểu sâu hơn.`:'Bạn đã trả lời đúng toàn bộ đề này. Hãy thử một đề hoặc kỹ năng khác.'}</p>${a.reviewUnlocked?`<button class="button primary" data-action="review">${icon('book')} Xem đáp án & chữa bài</button>${s.wrong+s.unanswered?`<button class="button secondary" data-action="retry-wrong">${icon('refresh')} Luyện lại câu sai / bỏ trống</button>`:''}`:`<div class="locked-review">${icon('lock')}<span>Chữa bài mở lúc ${timeLabel(a.reviewAt)}.<small id="review-countdown"></small></span></div><button class="button secondary" data-action="refresh-result">${icon('refresh')} Kiểm tra thời điểm mở</button>`}</section></div><button class="text-button result-history" data-nav="history">Xem lịch sử làm bài ${icon('arrow')}</button></main><footer class="auth-copyright">TOEIC Studio · Mỗi bước nhỏ đều đáng giá.</footer></div>`;
 if(!a.reviewUnlocked){ticker=setInterval(()=>{const el=$('#review-countdown');if(el)el.textContent='Còn '+formatTime(Math.ceil((a.reviewAt-Date.now())/1000));if(Date.now()>=a.reviewAt){clearInterval(ticker);api('/attempts/'+a.id).then(showResult).catch(err=>toast(err.message));}},1000);}
}
function openProfile(){modal(`<span class="eyebrow">MAKE IT YOURS</span><h2>Mục tiêu của riêng bạn</h2><p class="muted">Điều chỉnh một chút để hành trình phù hợp hơn.</p><form id="profile-form"><label>Họ và tên<input name="name" value="${esc(state.user.name)}" required maxlength="60"></label><label>Mục tiêu điểm TOEIC<input type="number" name="target" min="10" max="990" step="5" value="${state.user.target}" required></label><p class="tiny muted">Email: ${esc(state.user.email)}<br>Mục tiêu là thông tin cá nhân, không phải điểm dự đoán.</p><div class="form-error" role="alert"></div><button class="button primary full">Lưu thay đổi ${icon('check')}</button></form>`);}

document.addEventListener('click',async event=>{
 const btn=event.target.closest('button');if(!btn||btn.disabled)return;
 try{
  if(btn.dataset.nav){closeModal();await loadDashboard(btn.dataset.nav);return;}
  if(btn.dataset.exam){openSetup(btn.dataset.exam);return;}
  if(btn.dataset.resume){await openAttempt(btn.dataset.resume);return;}
  if(btn.dataset.result){showResult(await api('/attempts/'+btn.dataset.result));return;}
  if(btn.dataset.filter){state.filter=btn.dataset.filter;renderShell();return;}
  if(btn.dataset.answer!==undefined){const q=visibleQuestions()[state.index];if(state.review||questionLocked(q)||state.attempt.deadline&&Date.now()>=state.attempt.deadline)return;state.attempt.answers[q.id]=Number(btn.dataset.answer);keepDraft();syncAnswers();renderExam();return;}
  if(btn.dataset.step){const items=visibleQuestions();const next=state.index+Number(btn.dataset.step);if(items[next]&&questionLocked(items[next])){toast('Phần này hiện đang khóa theo thời gian thi.');return;}state.index=next;window.speechSynthesis?.cancel();renderExam();window.scrollTo(0,0);return;}
  if(btn.dataset.question){const i=visibleQuestions().findIndex(q=>q.id===Number(btn.dataset.question));if(i>=0){state.index=i;window.speechSynthesis?.cancel();renderExam();}return;}
  switch(btn.dataset.action){
   case 'auth-register':renderAuth(true);break;
   case 'auth-login':renderAuth();break;
   case 'demo':btn.disabled=true;try{state.user=(await api('/auth/demo','POST',{})).user;await loadDashboard('dashboard');}finally{btn.disabled=false;}break;
   case 'logout':await api('/auth/logout','POST',{});state.user=null;renderAuth();break;
   case 'close-modal':window.speechSynthesis?.cancel();closeModal();break;
   case 'menu':$('.sidebar').classList.toggle('mobile-open');break;
   case 'profile':openProfile();break;
   case 'notifications':modal(`<span class="modal-symbol sage">${icon('bell')}</span><h2>Một nhắc nhở nhẹ nhàng</h2><p class="muted">Bạn có 1 bài mẫu được giao: Bài kiểm tra tuần 01. Chữa bài sẽ mở sau 5 phút ở chế độ thi thử.</p><button class="button primary" data-nav="assigned">Xem bài được giao ${icon('arrow')}</button>`);break;
   case 'guide':modal(`<span class="eyebrow">BẮT ĐẦU THẬT DỄ</span><h2>Không gian học tập của bạn</h2><ol class="guide-list"><li><strong>Chọn đề & chế độ</strong><p>Thi thử có đếm ngược. Luyện tập không giới hạn thời gian.</p></li><li><strong>Kiểm tra âm thanh</strong><p>Nghe thử, xác nhận quy tắc rồi bắt đầu lượt thi riêng.</p></li><li><strong>Tập trung làm bài</strong><p>Chọn đáp án, đánh dấu câu cần xem lại. Bản nháp tự lưu sau mỗi lựa chọn.</p></li><li><strong>Nhìn lại & tiến bộ</strong><p>Nộp bài, xem kết quả từng Part, đọc giải thích, transcript và luyện lại câu sai.</p></li></ol><p class="tiny muted">Nếu mất kết nối, giữ nguyên trình duyệt và khởi động lại máy chủ. Thời gian thi vẫn tiếp tục tính.</p>`);break;
   case 'study-guide':modal(`<span class="modal-symbol sage">${icon('spark')}</span><span class="eyebrow">MỘT NHỊP HỌC NHẸ NHÀNG</span><h2>15 phút cũng tạo khác biệt.</h2><div class="study-plan"><div><b>05’</b><span>Ôn lại những câu sai của bài trước. Chú ý lý do bạn chọn nhầm.</span></div><div><b>07’</b><span>Luyện một nhóm câu nghe hoặc đọc. Tập trung vào một kỹ năng.</span></div><div><b>03’</b><span>Ghi lại từ vựng và một điều bạn vừa học được.</span></div></div><button class="button primary" data-nav="library">Bắt đầu từ hôm nay ${icon('arrow')}</button>`);break;
   case 'test-audio':{
    const el=$('#audio-check-status');el.textContent='Đang phát… Hãy nghe hết câu mẫu.';
    const ok=speak('Welcome to TOEIC Studio. You are ready to begin your English practice.',()=>{state.audioReady=true;const label=$('#audio-check-status');if(label)label.textContent='Đã phát xong. Xác nhận bên dưới nếu bạn nghe rõ.';});if(!ok)el.textContent='Không hỗ trợ âm thanh. Hãy mở bằng Chrome hoặc Edge.';break;
   }
   case 'play-question':speak(visibleQuestions()[state.index].audio);break;
   case 'flag':{const id=visibleQuestions()[state.index].id;if(state.review)return;state.attempt.flags=state.attempt.flags.includes(id)?state.attempt.flags.filter(x=>x!==id):[...state.attempt.flags,id];keepDraft();syncAnswers();renderExam();break;}
   case 'submit':requestSubmit();break;
   case 'confirm-submit':btn.disabled=true;await finishAttempt();btn.disabled=false;break;
   case 'retry-sync':if(state.attempt.deadline&&Date.now()>=state.attempt.deadline)await finishAttempt(true);else{await syncAnswers();if(state.sync==='saved')toast('Đáp án đã được đồng bộ.');}break;
   case 'leave-exam':await syncAnswers();if(state.sync!=='saved')toast('Bản nháp chưa đồng bộ vẫn được giữ trong trình duyệt.');await loadDashboard('dashboard');break;
   case 'review':state.review=true;state.wrongOnly=false;state.index=0;renderExam();break;
   case 'back-result':showResult(state.attempt);break;
   case 'refresh-result':showResult(await api('/attempts/'+state.attempt.id));break;
   case 'retry-wrong':{const a=await api('/attempts','POST',{examId:state.attempt.examId,mode:'practice',retryFrom:state.attempt.id});await openAttempt(a.id);break;}
  }
 }catch(err){toast(err.message||'Không thể kết nối. Kiểm tra máy chủ localhost.');}
});
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target;const error=form.querySelector('.form-error');if(error)error.textContent='';const btn=form.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;
 try{
  const b=Object.fromEntries(new FormData(form));
  if(form.id==='auth-form'){state.user=(await api('/auth/'+(form.dataset.register==='true'?'register':'login'),'POST',b)).user;await loadDashboard('dashboard');}
  if(form.id==='setup-form'){
   const e=state.data.exams.find(e=>e.id===form.dataset.examId);
   if(e.listeningMinutes&&(!state.audioReady||!$('#heard-audio').checked))throw new Error('Hãy phát hết audio mẫu và xác nhận bạn đã nghe rõ.');
   const a=await api('/attempts','POST',{examId:e.id,mode:b.mode});window.speechSynthesis?.cancel();closeModal();await openAttempt(a.id);
  }
  if(form.id==='profile-form'){state.user=(await api('/profile','PATCH',b)).user;closeModal();await loadDashboard('dashboard');toast('Đã lưu mục tiêu của bạn.');}
 }catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(btn)btn.disabled=false;}
});
document.addEventListener('input',event=>{if(event.target.id==='exam-search'){
 state.query=event.target.value;const position=event.target.selectionStart;$('.page-content').innerHTML=library();const input=$('#exam-search');input.focus();input.setSelectionRange(position,position);
}});
document.addEventListener('change',event=>{if(event.target.id==='wrong-filter'){
 const wrong=state.attempt.questions.filter(q=>state.attempt.answers[q.id]!==q.correct);if(event.target.checked&&!wrong.length){event.target.checked=false;toast('Bạn đã đúng toàn bộ câu hỏi.');return;}
 state.wrongOnly=event.target.checked;state.index=0;renderExam();
}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#modal-root').innerHTML){window.speechSynthesis?.cancel();closeModal();}if(event.key==='Tab'&&$('#modal-root').innerHTML){const controls=[...$('#modal-root').querySelectorAll('button:not(:disabled),input,select,summary')];const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('offline',()=>{state.online=false;if(state.attempt&&!state.review){state.sync='offline';saveBadge();toast('Mất kết nối. Bản nháp sẽ được giữ trên trình duyệt.');}});
window.addEventListener('online',()=>{state.online=true;if(state.attempt?.status==='active'&&!state.review){if(state.attempt.deadline&&Date.now()>=state.attempt.deadline)finishAttempt(true);else syncAnswers();}});
window.addEventListener('beforeunload',()=>{if(state.attempt?.status==='active')keepDraft();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.attempt&&!state.review)updateTimer();});
async function init(){try{state.user=(await api('/session')).user;if(state.user)await loadDashboard('dashboard');else renderAuth();}catch{$('#app').innerHTML=`<main class="boot-error">${brand()}<h1>Chưa kết nối được máy chủ</h1><p>Chạy <code>node server.mjs</code> trong thư mục dự án, rồi tải lại trang.</p><button class="button primary" onclick="location.reload()">Thử lại</button></main>`;}}
init();


